async function main() {
  const category = await prisma.interviewCategory.upsert({
    where: { slug: categorySlug },
    update: { name: "Python Developer" },
    create: { name: "Python Developer", slug: categorySlug },
  });

  const subcategories = [
    { name: "Python Fundamentals & Data Structures", slug: "python-fundamentals-data-structures" },
    { name: "Python Language & Runtime", slug: "python-language-runtime" },
    { name: "Python OOP & Object Model", slug: "python-oop-object-model" },
    { name: "Concurrency, Async & Parallelism", slug: "concurrency-async-parallelism" },
    { name: "Python Coding & Problem Solving", slug: "python-coding-problem-solving" },
    { name: "Python Backend, APIs & Testing", slug: "python-backend-apis-testing" },
    { name: "Python Performance & Production Engineering", slug: "python-performance-production" },
  ];

  const subcategoryMap = new Map<string, string>();
  for (const sub of subcategories) {
    const created = await prisma.interviewSubcategory.upsert({
      where: { slug: sub.slug },
      update: { name: sub.name, categoryId: category.id },
      create: { name: sub.name, slug: sub.slug, categoryId: category.id },
    });
    subcategoryMap.set(sub.slug, created.id);
  }

  for (const q of questions) {
    const subcategoryId = subcategoryMap.get(q.subcategorySlug);
    if (!subcategoryId) throw new Error(`Missing subcategory: ${q.subcategorySlug}`);

    await prisma.interviewQuestion.upsert({
      where: { slug: q.slug },
      update: {
        question: q.question,
        categoryId: category.id,
        subcategoryId,
        experienceLevel: q.experienceLevel,
        difficulty: q.difficulty,
        interviewType: q.interviewType,
        shortDescription: q.shortDescription,
        explanation: q.explanation,
        sampleAnswer: q.sampleAnswer,
        detailedAnswer: q.detailedAnswer,
        keyPoints: q.keyPoints,
        commonMistakes: q.commonMistakes,
        followUpQuestions: q.followUpQuestions,
        tags: q.tags,
        isPublished: true,
      },
      create: {
        question: q.question,
        slug: q.slug,
        categoryId: category.id,
        subcategoryId,
        experienceLevel: q.experienceLevel,
        difficulty: q.difficulty,
        interviewType: q.interviewType,
        shortDescription: q.shortDescription,
        explanation: q.explanation,
        sampleAnswer: q.sampleAnswer,
        detailedAnswer: q.detailedAnswer,
        keyPoints: q.keyPoints,
        commonMistakes: q.commonMistakes,
        followUpQuestions: q.followUpQuestions,
        tags: q.tags,
        isPublished: true,
      },
    });
  }

  console.log(`Python interview seed completed successfully: ${questions.length} questions.`);
}

main()
  .catch((error) => {
    console.error("Python interview seed failed:", error);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
